package br.com.loja.dashboard;import br.com.loja.order.*;import br.com.loja.product.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.math.*;import java.util.*;@RestController @RequestMapping("/api/dashboard")public class DashboardController{private final ProductRepository products;private final OrderRepository orders;public DashboardController(ProductRepository p,OrderRepository o){products=p;orders=o;}@GetMapping public Map<String,Object> summary(Authentication a){boolean admin=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));var os=admin?orders.findAll():orders.findByUserEmailOrderByCreatedAtDesc(a.getName());BigDecimal total=os.stream().filter(o->o.getStatus()!=OrderStatus.CANCELED).map(CustomerOrder::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add);long low=products.findAll().stream().filter(p->p.getStock()<=3).count();return Map.of("orders",os.size(),"total",total,"products",products.count(),"lowStock",low,"admin",admin);}}